415:   downloadPdf(resBase64String: string) {
416:     const base64String: string = resBase64String;
417:     const byteCharacters = atob(base64String);
418:     const byteNumbers = new Array(byteCharacters.length);
419:     for (let i = 0; i < byteCharacters.length; i++) {
420:       byteNumbers[i] = byteCharacters.charCodeAt(i);
421:     }
422:     const byteArray = new Uint8Array(byteNumbers);
423:     const blob = new Blob([byteArray], { type: 'application/pdf' });
424:     saveAs(blob, 'ListadOficializados.pdf');
425:   }
